    "ogHeadline": "NIGEL'S AJ6 'PAPERBOY'\nJUNE 25, 2027",
    "ogAccent": "2F6FE0",
    "heroImage": "https://www.sneakerfiles.com/wp-content/uploads/2026/07/nigel-sylvester-air-jordan-6-paperboy-blue.jpg",
