    "ogHeadline": "MADS IS 'THE ARCHER.'\nMW4 LANDS OCT. 23.",
    "ogAccent": "4A6B3A",
    "heroImage": "https://xboxwire.thesourcemediaassets.com/sites/2/2026/09/TGS_AnnounceStatic_2026-814e275774b1b96bd7e9.jpg",
